"use client";

import * as React from "react";
type IntegrationValues = {
  enabled: boolean;
  siteUrl: string;
  timeZone: string;
  apiKey: string | null;
};
interface IntegrationSettingsCleanProps {
  name?: string;
  logo?: React.ReactNode;
  count?: number;
  meta?: string;
  defaultValues?: Partial<IntegrationValues>;
  siteHint?: string;
  timeZones?: string[];
  onGenerateKey?: () => string | Promise<string>;
  onSave?: (values: IntegrationValues) => void | Promise<void>;
  onToggle?: (enabled: boolean) => void;
  className?: string;
}
var cleanTimeZones = [
  `(GMT −08:00) Los Angeles`,
  `(GMT −05:00) New York`,
  `(GMT −03:00) São Paulo`,
  `(GMT +00:00) London`,
  `(GMT +01:00) Berlin`,
  `(GMT +01:00) Amsterdam`,
  `(GMT +01:00) Warsaw`,
  `(GMT +02:00) Athens`,
  `(GMT +04:00) Dubai`,
  `(GMT +05:30) Mumbai`,
  `(GMT +08:00) Singapore`,
  `(GMT +09:00) Tokyo`,
  `(GMT +10:00) Sydney`,
];
var cleanDomainPattern = /^(?!-)[a-z0-9-]+(\.[a-z0-9-]+)*\.[a-z]{2,}$/i;
var normalizeCleanDomain = (value: string) =>
  value
    .trim()
    .replace(/^https?:\/\//i, ``)
    .replace(/\/+$/, ``);
function IntegrationSettingsClean({
  name: name,
  logo: logo,
  count: count,
  meta: meta,
  defaultValues: defaultValues,
  siteHint = `Your store's primary domain, without https://`,
  timeZones: zones = cleanTimeZones,
  onGenerateKey: onGenerateKey,
  onSave: onSave,
  onToggle: onToggle,
  className: className,
}: IntegrationSettingsCleanProps) {
  let initialValues = {
      enabled: true,
      siteUrl: ``,
      timeZone: zones[0],
      apiKey: null,
      ...defaultValues,
    },
    [saved, setSaved] = React.useState(initialValues),
    [draft, setDraft] = React.useState(initialValues),
    [keyStatus, setKeyStatus] = React.useState(`idle`),
    [revealed, setRevealed] = React.useState(false),
    [copied, setCopied] = React.useState(false),
    [saving, setSaving] = React.useState(false),
    siteId = React.useId(),
    hintId = React.useId(),
    normalizedSite = normalizeCleanDomain(draft.siteUrl),
    validSite = normalizedSite === `` || cleanDomainPattern.test(normalizedSite),
    dirty =
      draft.siteUrl !== saved.siteUrl ||
      draft.timeZone !== saved.timeZone ||
      draft.apiKey !== saved.apiKey,
    patchDraft = (patch: Partial<IntegrationValues>) =>
      setDraft((t) => ({
        ...t,
        ...patch,
      })),
    generateKey: React.MouseEventHandler<HTMLButtonElement> = async () => {
      if (keyStatus !== `busy`) {
        setKeyStatus(`busy`);
        try {
          let e = await (onGenerateKey
            ? onGenerateKey()
            : new Promise<string>((e) =>
                setTimeout(
                  () =>
                    e(
                      `sk_live_${Array.from(crypto.getRandomValues(new Uint8Array(16)), (e) => e.toString(16).padStart(2, `0`)).join(``)}`,
                    ),
                  700,
                ),
              ));
          (patchDraft({
            apiKey: e,
          }),
            setRevealed(true));
        } finally {
          setKeyStatus(`idle`);
        }
      }
    },
    copyKey: React.MouseEventHandler<HTMLButtonElement> = async () => {
      if (draft.apiKey)
        try {
          (await navigator.clipboard.writeText(draft.apiKey),
            setCopied(true),
            setTimeout(() => setCopied(false), 1400));
        } catch {}
    },
    save: React.MouseEventHandler<HTMLButtonElement> = async () => {
      if (!validSite || saving) return;
      setSaving(true);
      let e = {
        ...draft,
        siteUrl: normalizedSite,
      };
      try {
        (await onSave?.(e), setDraft(e), setSaved(e));
      } finally {
        setSaving(false);
      }
    },
    maskedKey = draft.apiKey
      ? `${draft.apiKey.slice(0, 8)}${`•`.repeat(14)}${draft.apiKey.slice(-4)}`
      : ``;
  return (
    <>
      <style href={`ui-integration-settings-clean`} precedence={`default`}>
        {integrationSettingsCleanStyles}
      </style>
      <section
        className={[`ui-isc`, className].filter(Boolean).join(` `)}
        aria-label={`${name} settings`}
        data-off={!draft.enabled || void 0}
      >
        <header className={`ui-isc__head`}>
          <span className={`ui-isc__logo`}>{logo}</span>
          <span className={`ui-isc__who`}>
            <span className={`ui-isc__name`}>
              <span className={`ui-isc__name-text`}>{name}</span>
              {count !== void 0 && (
                <span className={`ui-isc__count`}>{count.toLocaleString(`en-US`)}</span>
              )}
            </span>
            <span className={`ui-isc__meta`}>
              {draft.enabled ? meta : `Paused – no data is synced`}
            </span>
          </span>
          <button
            type={`button`}
            role={`switch`}
            aria-checked={draft.enabled}
            aria-label={`${name} sync`}
            className={`ui-isc__switch`}
            onClick={() => {
              let e = !draft.enabled;
              (patchDraft({
                enabled: e,
              }),
                setSaved((t) => ({
                  ...t,
                  enabled: e,
                })),
                onToggle?.(e));
            }}
          >
            <span />
          </button>
        </header>
        <div className={`ui-isc__fold`} data-open={draft.enabled || void 0} inert={!draft.enabled}>
          <div className={`ui-isc__fold-inner`}>
            <div className={`ui-isc__section`}>
              <span className={`ui-isc__label`}>{`API key`}</span>
              {draft.apiKey ? (
                <div className={`ui-isc__key`} data-new={revealed || void 0}>
                  <code>{revealed ? draft.apiKey : maskedKey}</code>
                  <button
                    type={`button`}
                    className={`ui-isc__mini`}
                    aria-label={revealed ? `Hide key` : `Show key`}
                    onClick={() => setRevealed((e) => !e)}
                  >
                    <CleanPathIcon
                      d={
                        revealed
                          ? `M2 8s2.2-4.5 6-4.5S14 8 14 8s-2.2 4.5-6 4.5S2 8 2 8ZM2.5 2.5l11 11`
                          : `M2 8s2.2-4.5 6-4.5S14 8 14 8s-2.2 4.5-6 4.5S2 8 2 8ZM8 9.8a1.8 1.8 0 1 0 0-3.6 1.8 1.8 0 0 0 0 3.6Z`
                      }
                    />
                  </button>
                  <button
                    type={`button`}
                    className={`ui-isc__mini`}
                    aria-label={`Copy key`}
                    onClick={copyKey}
                  >
                    <CleanPathIcon
                      d={
                        copied
                          ? `m3.5 8.5 3 3 6-7`
                          : `M5.5 5.5V3.5a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v6a1 1 0 0 1-1 1h-2M3.5 5.5h6a1 1 0 0 1 1 1v6a1 1 0 0 1-1 1h-6a1 1 0 0 1-1-1v-6a1 1 0 0 1 1-1Z`
                      }
                    />
                  </button>
                  <button
                    type={`button`}
                    className={`ui-isc__regen`}
                    onClick={generateKey}
                    disabled={keyStatus === `busy`}
                  >
                    {keyStatus === `busy` ? (
                      <span className={`ui-isc__spinner`} aria-hidden={`true`} />
                    ) : (
                      `Regenerate`
                    )}
                  </button>
                </div>
              ) : (
                <button
                  type={`button`}
                  className={`ui-isc__generate`}
                  onClick={generateKey}
                  disabled={keyStatus === `busy`}
                >
                  {keyStatus === `busy` ? (
                    <span
                      className={`ui-isc__shimmer`}
                      data-text={`Generating…`}
                    >{`Generating…`}</span>
                  ) : (
                    <span>{`Generate a new API key`}</span>
                  )}
                  <CleanGenerateKeyIcon />
                </button>
              )}
              {draft.apiKey && revealed && (
                <p className={`ui-isc__note`} role={`status`}>
                  {copied
                    ? `Copied to the clipboard.`
                    : `Copy it now – it is shown in full only once.`}
                </p>
              )}
            </div>
            <div className={`ui-isc__section`}>
              <label className={`ui-isc__label`} htmlFor={siteId}>{`Site address`}</label>
              <div className={`ui-isc__field`} data-invalid={!validSite || void 0}>
                <span className={`ui-isc__prefix`}>{`https://`}</span>
                <input
                  id={siteId}
                  value={draft.siteUrl}
                  onChange={(e) =>
                    patchDraft({
                      siteUrl: e.target.value.replace(/^https?:\/\//i, ``),
                    })
                  }
                  placeholder={`yourstore.com`}
                  inputMode={`url`}
                  autoComplete={`off`}
                  spellCheck={false}
                  aria-invalid={!validSite}
                  aria-describedby={hintId}
                />
                {normalizedSite && validSite && (
                  <span className={`ui-isc__ok`} aria-hidden={`true`}>
                    <CleanPathIcon d={`m3.5 8.5 3 3 6-7`} />
                  </span>
                )}
              </div>
              <p className={`ui-isc__hint`} id={hintId} data-error={!validSite || void 0}>
                {validSite
                  ? siteHint
                  : `That doesn't look like a domain – try something like yourstore.com`}
              </p>
            </div>
            <div className={`ui-isc__section`}>
              <span className={`ui-isc__label`} id={`${siteId}-tz`}>{`Time zone`}</span>
              <TimeZonePickerClean
                zones={zones}
                value={draft.timeZone}
                onChange={(e) =>
                  patchDraft({
                    timeZone: e,
                  })
                }
                labelledBy={`${siteId}-tz`}
              />
            </div>
            <div className={`ui-isc__save`} data-open={dirty || void 0} inert={!dirty}>
              <div className={`ui-isc__save-inner`}>
                <span className={`ui-isc__save-text`}>{`Unsaved changes`}</span>
                <div className={`ui-isc__save-actions`}>
                  <button
                    type={`button`}
                    className={`ui-isc__btn`}
                    onClick={() => setDraft(saved)}
                  >{`Discard`}</button>
                  <button
                    type={`button`}
                    className={`ui-isc__btn ui-isc__btn--primary`}
                    onClick={save}
                    disabled={!validSite || saving}
                  >
                    {saving ? `Saving…` : `Save`}
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>
    </>
  );
}
function TimeZonePickerClean({
  zones: zones,
  value: value,
  onChange: onChange,
  labelledBy: labelledBy,
}: {
  zones: string[];
  value: string;
  onChange: (value: string) => void;
  labelledBy: string;
}) {
  let [open, setOpen] = React.useState<boolean>(false),
    [query, setQuery] = React.useState<string>(``),
    rootRef = React.useRef<HTMLDivElement | null>(null);
  React.useEffect(() => {
    if (!open) return;
    let e = (e: PointerEvent) =>
        !rootRef.current?.contains(e.target as Node | null) && setOpen(false),
      t = (e: { key: string }) => e.key === `Escape` && setOpen(false);
    return (
      window.addEventListener(`pointerdown`, e),
      window.addEventListener(`keydown`, t),
      () => {
        (window.removeEventListener(`pointerdown`, e), window.removeEventListener(`keydown`, t));
      }
    );
  }, [open]);
  let filteredZones = React.useMemo(
    () => zones.filter((e: string) => e.toLowerCase().includes(query.trim().toLowerCase())),
    [zones, query],
  );
  return (
    <div className={`ui-isc__zone`} ref={rootRef}>
      <button
        type={`button`}
        className={`ui-isc__field ui-isc__zone-btn`}
        aria-haspopup={`listbox`}
        aria-expanded={open}
        aria-labelledby={labelledBy}
        onClick={() => {
          (setOpen((e) => !e), setQuery(``));
        }}
      >
        <span className={`ui-isc__zone-value`}>{value}</span>
        <CleanTimeZoneIcon />
      </button>
      {open && (
        <div className={`ui-isc__menu`}>
          <div className={`ui-isc__menu-search`}>
            <CleanPathIcon d={`M7 12a5 5 0 1 0 0-10 5 5 0 0 0 0 10ZM13.5 13.5 10.6 10.6`} />
            <input
              autoFocus={true}
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder={`Search city or offset`}
              aria-label={`Search time zones`}
            />
          </div>
          <div className={`ui-isc__menu-list`} role={`listbox`} aria-labelledby={labelledBy}>
            {filteredZones.length === 0 && (
              <p className={`ui-isc__menu-empty`}>{`No time zone matches.`}</p>
            )}
            {filteredZones.map((e) => (
              <button
                type={`button`}
                role={`option`}
                aria-selected={e === value}
                className={`ui-isc__option`}
                onClick={() => {
                  (onChange(e), setOpen(false));
                }}
                key={e}
              >
                {e}
                {e === value && <CleanPathIcon d={`m3.5 8.5 3 3 6-7`} />}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
var CleanGenerateKeyIcon = () => (
  <svg
    className={`ui-isc__glyph-solid`}
    viewBox={`0 0 16 16`}
    width={`16`}
    height={`16`}
    fill={`currentColor`}
    aria-hidden={`true`}
  >
    <path
      d={`M10.5 1.5a4 4 0 0 0-3.86 5.05L1.8 11.4a1 1 0 0 0-.3.7v1.9a.5.5 0 0 0 .5.5h1.9a.5.5 0 0 0 .5-.5V13h1v-1h1v-1l.95-.95A4 4 0 1 0 10.5 1.5Zm1 4a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z`}
    />
  </svg>
);
var CleanTimeZoneIcon = () => (
  <CleanPathIcon d={`M8 14.5a6.5 6.5 0 1 0 0-13 6.5 6.5 0 0 0 0 13ZM8 4.5V8l2.5 1.5`} />
);
var CleanPathIcon = ({ d: path, size = 16 }: { d: string; size?: number }) => (
  <svg
    className={`ui-isc__glyph`}
    viewBox={`0 0 16 16`}
    width={size}
    height={size}
    fill={`none`}
    stroke={`currentColor`}
    strokeWidth={`1.2`}
    strokeLinecap={`round`}
    strokeLinejoin={`round`}
    aria-hidden={`true`}
  >
    <path d={path} />
  </svg>
);
var integrationSettingsCleanStyles = `
/* Colors and motion as variables – override them on .ui-isc */
.ui-isc {
  --ui-isc-card: #ffffff;
  --ui-isc-ink: rgba(0, 0, 0, 0.88);
  --ui-isc-strong: #000000;
  --ui-isc-text: rgba(0, 0, 0, 0.61);
  --ui-isc-muted: rgba(0, 0, 0, 0.45);
  --ui-isc-faint: rgba(0, 0, 0, 0.27);
  --ui-isc-icon: rgba(0, 0, 0, 0.447);
  --ui-isc-line: rgba(0, 0, 0, 0.06);
  --ui-isc-fill: rgba(0, 0, 0, 0.06);
  --ui-isc-fill-strong: rgba(0, 0, 0, 0.1);
  --ui-isc-wash: rgba(0, 0, 0, 0.03);
  --ui-isc-accent: rgba(0, 96, 226, 0.765);
  --ui-isc-ok: #1a9a52;
  --ui-isc-ok-soft: rgba(26, 154, 82, 0.08);
  --ui-isc-danger: #e5484d;
  --ui-isc-danger-soft: rgba(229, 72, 77, 0.08);
  --ui-isc-solid: rgba(0, 0, 0, 0.88);
  --ui-isc-solid-hover: rgba(0, 0, 0, 0.8);
  --ui-isc-on-solid: #fcfcfc;
  --ui-isc-switch-off: rgba(0, 0, 0, 0.12);
  --ui-isc-shine: rgba(255, 255, 255, 0.82);
  /* Strokes are shadows: a 0.5px hairline plus a soft lift */
  --ui-isc-shadow: 0 0 0 0.5px rgba(0, 0, 0, 0.06), 0 1px 1px -1px rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --ui-isc-shadow-hover: 0 0 0 0.5px rgba(0, 0, 0, 0.12), 0 1px 1px -1px rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --ui-isc-shadow-pop: 0 0 0 0.5px rgba(0, 0, 0, 0.08), 0 12px 28px -10px rgba(0, 0, 0, 0.16), 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --ui-isc-focus: rgba(0, 96, 226, 0.35);
  --ui-isc-ease: cubic-bezier(0.22, 1, 0.36, 1);
  box-sizing: border-box;
  container-type: inline-size;
  width: 100%;
  max-width: 560px;
  /* One white card – the edge is a shadow, not a border */
  border-radius: 10px;
  background: var(--ui-isc-card);
  box-shadow: var(--ui-isc-shadow);
  font-family: "Inter", "InterVariable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 13px;
  line-height: 20px;
  font-weight: 400;
  color: var(--ui-isc-ink);
  -webkit-font-smoothing: antialiased;
}
.ui-isc *, .ui-isc *::before, .ui-isc *::after { box-sizing: border-box; }
:where(.ui-isc) button { margin: 0; padding: 0; border: 0; background: none; font: inherit; color: inherit; cursor: pointer; }
:where(.ui-isc) svg { display: block; flex: none; }
.ui-isc button:focus-visible { outline: 2px solid var(--ui-isc-focus); outline-offset: 1px; }

/* Header: logo tile, name with count, meta line and the switch */
.ui-isc__head { display: flex; align-items: center; gap: 12px; padding: 16px; }
.ui-isc__logo {
  display: grid;
  place-items: center;
  flex: none;
  width: 40px;
  height: 40px;
  border-radius: 8px;
  background: var(--ui-isc-card);
  box-shadow: var(--ui-isc-shadow);
}
.ui-isc__logo svg { width: 22px; height: 22px; }
.ui-isc__who { display: grid; flex: 1; min-width: 0; }
.ui-isc__name { display: flex; align-items: center; gap: 8px; min-width: 0; font-size: 15px; line-height: 24px; font-weight: 500; color: var(--ui-isc-strong); }
.ui-isc__name-text { min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.ui-isc__count {
  flex: none;
  padding: 0 5px;
  border-radius: 5px;
  background: var(--ui-isc-fill);
  font-size: 11px;
  line-height: 16px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  color: var(--ui-isc-text);
}
.ui-isc__meta { overflow: hidden; font-size: 12px; line-height: 16px; white-space: nowrap; text-overflow: ellipsis; color: var(--ui-isc-muted); }

/* A small switch: 28×16, white knob with the card shadow */
.ui-isc__switch {
  position: relative;
  flex: none;
  width: 28px;
  height: 16px;
  border-radius: 8px;
  background: var(--ui-isc-switch-off) !important;
  transition: background-color 220ms ease;
}
.ui-isc__switch[aria-checked="true"] { background: var(--ui-isc-accent) !important; }
.ui-isc__switch span {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #fff;
  box-shadow: var(--ui-isc-shadow);
  transition: transform 280ms var(--ui-isc-ease);
}
.ui-isc__switch[aria-checked="true"] span { transform: translateX(12px); }
/* A bigger invisible hit area around the small switch */
.ui-isc__switch::after { content: ""; position: absolute; inset: -8px -6px; }

/* Switching off folds the settings away – only this part animates, the header stays */
.ui-isc__fold { display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: 0fr; opacity: 0; transition: grid-template-rows 420ms var(--ui-isc-ease), opacity 260ms ease; }
.ui-isc__fold[data-open] { grid-template-rows: 1fr; opacity: 1; }
.ui-isc__fold-inner { min-width: 0; min-height: 0; overflow: hidden; }
.ui-isc__fold[data-open] .ui-isc__fold-inner { overflow: visible; }

/* Sections sit right in the card, split by hairlines */
.ui-isc__section { padding: 14px 16px 16px; border-top: 0.5px solid var(--ui-isc-line); }
.ui-isc__label { display: block; margin: 0 0 6px; font-size: 13px; line-height: 20px; font-weight: 500; color: var(--ui-isc-ink); }

/* No key yet: a quiet full-width slot */
.ui-isc__generate {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  height: 32px;
  padding: 0 8px 0 10px !important;
  border-radius: 8px;
  background: var(--ui-isc-wash) !important;
  box-shadow: inset 0 0 0 0.5px var(--ui-isc-line);
  color: var(--ui-isc-text) !important;
  text-align: left;
  transition: background-color 160ms ease, color 160ms ease;
}
.ui-isc__generate svg { color: var(--ui-isc-icon); transition: color 160ms ease; }
.ui-isc__generate:hover:not(:disabled) { background: var(--ui-isc-fill) !important; color: var(--ui-isc-ink) !important; }
.ui-isc__generate:hover:not(:disabled) svg { color: var(--ui-isc-ink); }
.ui-isc__generate:disabled { cursor: progress; }

/* The key: a field-like row with ghost buttons; a fresh key gets a light green fill */
.ui-isc__key {
  display: flex;
  align-items: center;
  gap: 2px;
  height: 36px;
  padding: 0 4px 0 10px;
  border-radius: 8px;
  background: var(--ui-isc-card);
  box-shadow: var(--ui-isc-shadow);
  transition: background-color 240ms ease;
  animation: ui-isc-in 320ms var(--ui-isc-ease);
}
.ui-isc__key[data-new] { background: var(--ui-isc-ok-soft); box-shadow: none; }
.ui-isc__key code {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  line-height: 16px;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--ui-isc-ink);
}
.ui-isc__mini {
  display: grid;
  place-items: center;
  flex: none;
  width: 28px;
  height: 28px;
  border-radius: 6px;
  color: var(--ui-isc-icon) !important;
  transition: background-color 140ms ease, color 140ms ease;
}
.ui-isc__mini:hover { background: var(--ui-isc-wash) !important; color: var(--ui-isc-ink) !important; }
.ui-isc__key[data-new] .ui-isc__mini:hover { background: var(--ui-isc-fill) !important; }
.ui-isc__regen {
  display: grid;
  place-items: center;
  flex: none;
  min-width: 88px;
  height: 28px;
  margin-left: 2px;
  padding: 0 10px !important;
  border-radius: 6px;
  background: var(--ui-isc-card) !important;
  box-shadow: var(--ui-isc-shadow);
  font-size: 13px;
  font-weight: 500;
  color: var(--ui-isc-strong) !important;
  transition: box-shadow 140ms ease;
}
.ui-isc__regen:hover:not(:disabled) { box-shadow: var(--ui-isc-shadow-hover); }
.ui-isc__regen:disabled { cursor: progress; }
